(11,51,E'Bank account (encapsulation)',E'1000\n500\n200',E'1300',E'class Acc:\n    def __init__(self, b):\n        self.__b = b\n    def deposit(self, x):\n        self.__b += x\n    def withdraw(self, x):\n        if x <= self.__b:\n            self.__b -= x\n    def balance(self):\n        return self.__b\na = Acc(int(input()))\na.deposit(int(input()))\na.withdraw(int(input()))\nprint(a.balance())',E'__b private; methods ద్వారా మాత్రమే మారుతుంది.',null,null),
