(17,80,E'Route table with decorator',E'/about',E'This is the About Page',E'routes = {}\ndef route(p):\n    def d(f):\n        routes[p] = f\n        return f\n    return d\n@route(''/'')\ndef home():\n    return ''Welcome to the Home Page''\n@route(''/about'')\ndef about():\n    return ''This is the About Page''\nprint(routes[input()]())',E'@app.route ఇలాగే URL ని function కి map చేస్తుంది (Flask లేకుండా simulate).',null,null),
(17,81,E'Dynamic route',E'/user/Nihar',E'Hello, Nihar!',E'def user(name):\n    return f''Hello, {name}!''\nparts = input().strip(''/'').split(''/'')\nif parts[0] == ''user'':\n    print(user(parts[1]))\nelse:\n    print(''404 Not Found'')',E'/user/<name> లో name URL నుండి వచ్చే parameter.',null,null),
(17,82,E'jsonify a user',E'1',E'{"id": 1, "name": "Alice"}',E'import json\nusers = [{''id'': 1, ''name'': ''Alice''}, {''id'': 2, ''name'': ''Bob''}]\nuid = int(input())\nu = next((x for x in users if x[''id''] == uid), None)\nprint(json.dumps(u) if u else json.dumps({''error'': ''User not found''}))',E'jsonify dict ని JSON response చేస్తుంది; లేకపోతే error JSON.',null,null),
(17,83,E'Handle POST form',E'POST\nNihar',E'Hello, Nihar!',E'method = input()\nif method == ''POST'':\n    name = input()\n    print(f''Hello, {name}!'')\nelse:\n    print(''<form method="post">'')',E'request.method చూసి POST అయితే form data చదువుతాం.',null,null),
(17,84,E'Allowed HTTP methods',E'DELETE',E'405 Method Not Allowed',E'allowed = {''GET'', ''POST''}\nm = input().upper()\nprint(''OK'' if m in allowed else ''405 Method Not Allowed'')',E'methods=[...] లో లేని method కి 405 వస్తుంది.',null,null),
(201,85,E'FizzBuzz',E'5',E'1\n2\nFizz\n4\nBuzz',E'for i in range(1, int(input()) + 1):\n    print(''FizzBuzz'' if i % 15 == 0 else ''Fizz'' if i % 3 == 0 else ''Buzz'' if i % 5 == 0 else i)',E'15 check ముందు పెట్టాలి; లేకపోతే Fizz మాత్రమే వస్తుంది.',E'for i in range(1, int(input()) + 1):\n    s = (''Fizz'' if i % 3 == 0 else '''') + (''Buzz'' if i % 5 == 0 else '''')\n    print(s or i)',E'Strings జోడించి, ఖాళీ అయితే number print.'),
(201,86,E'Roman numerals',E'1994',E'MCMXCIV',E'n = int(input())\nr = ''''\nfor v, s in [(1000, ''M''), (900, ''CM''), (500, ''D''), (400, ''CD''), (100, ''C''), (90, ''XC''), (50, ''L''), (40, ''XL''), (10, ''X''), (9, ''IX''), (5, ''V''), (4, ''IV''), (1, ''I'')]:\n    while n >= v:\n        r += s\n        n -= v\nprint(r)',E'Greedy: పెద్ద value నుండి తగ్గిస్తూ; subtractive pairs (CM, XC) list లో చేర్చాం.',E'n = int(input())\nth = ['''', ''M'', ''MM'', ''MMM'']\nh = ['''', ''C'', ''CC'', ''CCC'', ''CD'', ''D'', ''DC'', ''DCC'', ''DCCC'', ''CM'']\nt = ['''', ''X'', ''XX'', ''XXX'', ''XL'', ''L'', ''LX'', ''LXX'', ''LXXX'', ''XC'']\no = ['''', ''I'', ''II'', ''III'', ''IV'', ''V'', ''VI'', ''VII'', ''VIII'', ''IX'']\nprint(th[n // 1000] + h[n // 100 % 10] + t[n // 10 % 10] + o[n % 10])',E'ప్రతి digit కి lookup table: వేగంగా, loop లేదు.');
